#pragma GCC optimize("Ofast")
#include <bits/stdc++.h>
using namespace std;
using i64 = int_least64_t;

// Combined class, use set for Dijkstra, use custom I/O with cin/cout but disable sync
struct Edge {
    size_t src, dst;
    int cap; i64 cost;
    Edge *rev;
    Edge(size_t s, size_t d, int c, i64 co, Edge *r) : src(s), dst(d), cap(c), cost(co), rev(r) {}
};

class MinCostFlow {
    size_t n;
    vector<vector<Edge>> adj;
    vector<int> supp;
    vector<i64> ptnl;
    i64 min_cost, total_cost;
public:
    MinCostFlow(size_t _n) : n(_n), adj(_n), supp(_n, 0), ptnl(_n, 0), min_cost(0), total_cost(0) {}
    size_t size() const { return n; }
    void add_edge(size_t src, size_t dst, int cap, i64 cost) {
        if (cap <= 0) return;
        if (cost < 0) {
            supp[src] -= cap;
            supp[dst] += cap;
            min_cost += cap * cost;
            total_cost -= cap * cost;
            adj[dst].push_back(Edge(dst, src, cap, -cost, nullptr));
            adj[src].push_back(Edge(src, dst, 0, cost, nullptr));
            adj[dst].back().rev = &adj[src].back();
            adj[src].back().rev = &adj[dst].back();
        } else {
            total_cost += cap * cost;
            adj[src].push_back(Edge(src, dst, cap, cost, nullptr));
            adj[dst].push_back(Edge(dst, src, 0, -cost, nullptr));
            adj[src].back().rev = &adj[dst].back();
            adj[dst].back().rev = &adj[src].back();
        }
    }
    void supply(size_t node, int vol) { supp[node] += vol; }
    bool flow() {
        const i64 infty = total_cost + 1;
        for (bool aug = true; aug; ) {
            aug = false;
            vector<Edge*> last(n, nullptr);
            vector<i64> dist(n, infty);
            set<pair<i64, size_t>> pq;
            for (size_t node = 0; node < n; ++node) {
                if (supp[node] > 0) {
                    dist[node] = 0;
                    pq.insert({0, node});
                }
            }
            while (!pq.empty()) {
                auto it = pq.begin();
                i64 d = it->first;
                size_t node = it->second;
                pq.erase(it);
                if (d != dist[node]) continue;
                ptnl[node] -= d;
                if (ptnl[node] > infty) ptnl[node] = infty;
                dist[node] = infty; // mark as processed
                for (Edge &e : adj[node]) {
                    if (e.cap == 0) continue;
                    i64 nd = ptnl[node] + e.cost - ptnl[e.dst];
                    if (nd < dist[e.dst]) {
                        pq.erase({dist[e.dst], e.dst});
                        dist[e.dst] = nd;
                        last[e.dst] = &e;
                        pq.insert({nd, e.dst});
                    }
                }
            }
            vector<bool> shut(n, false);
            for (size_t dst = 0; dst < n; ++dst) {
                if (supp[dst] < 0 && last[dst]) {
                    int resid = -supp[dst];
                    size_t src = dst, block = n;
                    while (last[src] && !shut[src]) {
                        if (resid >= last[src]->cap) resid = last[block = src]->cap;
                        src = last[src]->src;
                    }
                    if (shut[src]) block = src;
                    else {
                        if (resid >= supp[src]) {
                            resid = supp[src];
                            block = src;
                        }
                        for (size_t node = dst; node != src; node = last[node]->src) {
                            last[node]->cap -= resid;
                            last[node]->rev->cap += resid;
                        }
                        supp[src] -= resid;
                        supp[dst] += resid;
                        min_cost += ptnl[dst] * resid;
                        aug = true;
                    }
                    if (block != n) {
                        for (size_t node = dst; node != block; node = last[node]->src) shut[node] = true;
                        shut[block] = true;
                    }
                }
            }
        }
        for (int s : supp) if (s > 0) return false;
        return true;
    }
    i64 optimal() { return flow() ? min_cost : -1; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    const int tlim = 105;
    MinCostFlow mcf(6100);
    for (int i = 0; i < k; ++i) {
        int j; cin >> j; j--;
        mcf.supply(j, 1);
    }
    for (int i = 0; i < m; ++i) {
        int u, v; cin >> u >> v; --u; --v;
        for (int t = 0; t < tlim; ++t) {
            int nu = u + n;
            int nv = v + n;
            for (int x = 0; x < k; ++x) {
                mcf.add_edge(u, nv, 1, c + d * (x * 2 + 1));
                mcf.add_edge(v, nu, 1, c + d * (x * 2 + 1));
            }
            u = nu;
            v = nv;
        }
    }
    for (int i = 1; i < n; ++i) {
        for (int t = 0; t < tlim; t++) {
            mcf.add_edge(n * t + i, n * (t + 1) + i, k, c);
        }
    }
    const int dst = mcf.size() - 1;
    mcf.supply(dst, -k);
    for (int t = 0; t <= tlim; ++t) mcf.add_edge(t * n, dst, k, 0);
    cout << mcf.optimal() << "\n";
    return 0;
}
